import React, { useState } from 'react';
import { CheckCircle2, XCircle, Send, Sparkles, Moon, Star, Zap } from 'lucide-react';
import { DayData, TomorrowPlan } from '../types';

interface NightReviewProps {
  dayData: DayData;
  onComplete: (note: string, plan: TomorrowPlan) => void;
  onClose: () => void;
}

const NightReview: React.FC<NightReviewProps> = ({ dayData, onComplete, onClose }) => {
  const [note, setNote] = useState('');
  const [plan, setPlan] = useState<TomorrowPlan>({ englishTopic: '', tradingStrategy: '', dsaTopic: '', flutterReactChapter: '' });
  const [submitting, setSubmitting] = useState(false);
  const [step, setStep] = useState<'review' | 'plan'>('review');

  const completed = dayData.tasks.filter(t => t.completed).length;
  const total = dayData.tasks.length;
  const pct = Math.round((completed / total) * 100);

  const grade = pct >= 95 ? { g: 'A+', color: '#10B981', glow: 'grade-glow-green', desc: 'Elite Performance!' }
    : pct >= 85 ? { g: 'A', color: '#4F8EF7', glow: 'grade-glow-blue', desc: 'Excellent Work!' }
    : pct >= 70 ? { g: 'B', color: '#6366F1', glow: 'grade-glow-blue', desc: 'Good Progress.' }
    : pct >= 50 ? { g: 'C', color: '#F59E0B', glow: '', desc: 'Needs Improvement.' }
    : { g: 'F', color: '#F87171', glow: 'grade-glow-red', desc: 'Missed the Mark.' };

  const handleLock = () => {
    setSubmitting(true);
    if (typeof window !== 'undefined' && pct >= 80) {
      import('canvas-confetti').then(({ default: confetti }) => {
        confetti({ particleCount: 120, spread: 70, origin: { y: 0.6 }, colors: ['#4F8EF7','#8B5CF6','#10B981'] });
      });
    }
    setTimeout(() => onComplete(note, plan), 800);
  };

  const earnedPts = dayData.tasks.filter(t => t.completed).reduce((s, t) => s + t.points, 0);

  return (
    <div className="modal-backdrop" style={{ position: 'fixed', inset: 0, zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24 }}>
      <div onClick={onClose} style={{ position: 'absolute', inset: 0 }} />

      {/* Modal */}
      <div style={{ position: 'relative', width: '100%', maxWidth: 920, maxHeight: '92vh', display: 'flex', borderRadius: 28, overflow: 'hidden', boxShadow: '0 40px 80px rgba(0,0,0,0.9), 0 0 0 1px rgba(255,255,255,0.07)', background: '#0D1120', animation: 'pop-in 0.35s cubic-bezier(0.34,1.56,0.64,1)' }}>

        {/* Left: Review Panel */}
        <div style={{ width: '44%', background: 'rgba(255,255,255,0.02)', borderRight: '1px solid rgba(255,255,255,0.06)', padding: '36px 32px', display: 'flex', flexDirection: 'column', gap: 24, overflowY: 'auto' }}>
          {/* Header */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ width: 44, height: 44, borderRadius: 14, background: 'rgba(79,142,247,0.1)', border: '1px solid rgba(79,142,247,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Moon size={22} color="#4F8EF7" />
            </div>
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: '#F1F5F9', fontFamily: "'Space Grotesk',sans-serif" }}>Day {dayData.day} Complete</div>
              <div style={{ fontSize: 11, color: '#475569', fontWeight: 600, letterSpacing: '0.1em', textTransform: 'uppercase' }}>Night Review</div>
            </div>
          </div>

          {/* Grade Box */}
          <div style={{ padding: '28px', borderRadius: 20, background: `${grade.color}0D`, border: `1px solid ${grade.color}33`, textAlign: 'center', position: 'relative', overflow: 'hidden' }}>
            <div style={{ position: 'absolute', inset: 0, background: `radial-gradient(circle at 50% 0%, ${grade.color}15, transparent 70%)` }} />
            <div style={{ position: 'relative', zIndex: 1 }}>
              <div className={grade.glow} style={{ fontSize: 80, fontWeight: 900, color: grade.color, fontFamily: "'Space Grotesk',sans-serif", lineHeight: 1, marginBottom: 8 }}>{grade.g}</div>
              <div style={{ fontSize: 13, color: grade.color, fontWeight: 700, marginBottom: 16 }}>{grade.desc}</div>
              <div style={{ width: '100%', height: 6, background: 'rgba(255,255,255,0.05)', borderRadius: 99, overflow: 'hidden', marginBottom: 8 }}>
                <div style={{ width: `${pct}%`, height: '100%', background: grade.color, borderRadius: 99, boxShadow: `0 0 10px ${grade.color}`, transition: 'width 1s ease' }} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, color: '#64748B', fontWeight: 600 }}>
                <span>{completed} of {total} done</span><span>{pct}%</span>
              </div>
            </div>
          </div>

          {/* Points earned */}
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 20px', background: 'rgba(79,142,247,0.06)', borderRadius: 16, border: '1px solid rgba(79,142,247,0.15)' }}>
            <span style={{ fontSize: 13, color: '#94A3B8', fontWeight: 600 }}>Points Earned Today</span>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <Zap size={16} fill="#F59E0B" color="#F59E0B" />
              <span style={{ fontSize: 22, fontWeight: 800, color: '#F59E0B', fontFamily: "'Space Grotesk',sans-serif" }}>+{earnedPts}</span>
            </div>
          </div>

          {/* Task list */}
          <div>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 12 }}>Task Breakdown</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 220, overflowY: 'auto', paddingRight: 4 }}>
              {dayData.tasks.map(t => (
                <div key={t.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', borderRadius: 12, background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.04)' }}>
                  {t.completed ? <CheckCircle2 size={15} color="#10B981" /> : <XCircle size={15} color="#F87171" />}
                  <span style={{ flex: 1, fontSize: 12, fontWeight: 500, color: t.completed ? '#94A3B8' : '#64748B', textDecoration: t.completed ? 'line-through' : 'none', lineHeight: 1.3 }}>{t.title}</span>
                  {t.completed && <span style={{ fontSize: 11, color: '#10B981', fontWeight: 700 }}>+{t.points}</span>}
                </div>
              ))}
            </div>
          </div>

          {/* Reflection note */}
          <div>
            <label style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase', display: 'block', marginBottom: 10 }}>Today's Reflection</label>
            <textarea
              value={note}
              onChange={e => setNote(e.target.value)}
              placeholder="What did you learn? What would you do differently?"
              className="input-field"
              style={{ height: 100, resize: 'none', fontFamily: "'Inter',sans-serif" }}
            />
          </div>
        </div>

        {/* Right: Plan Tomorrow */}
        <div style={{ flex: 1, padding: '36px 32px', display: 'flex', flexDirection: 'column', gap: 24, overflowY: 'auto', background: 'linear-gradient(135deg, rgba(79,142,247,0.03), transparent)' }}>
          {/* Header */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <div style={{ width: 44, height: 44, borderRadius: 14, background: 'rgba(139,92,246,0.1)', border: '1px solid rgba(139,92,246,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Sparkles size={22} color="#8B5CF6" />
            </div>
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: '#F1F5F9', fontFamily: "'Space Grotesk',sans-serif" }}>Plan Tomorrow</div>
              <div style={{ fontSize: 11, color: '#475569', fontWeight: 600, letterSpacing: '0.1em', textTransform: 'uppercase' }}>Set your focus for Day {dayData.day + 1}</div>
            </div>
            {pct === 100 && (
              <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6, padding: '6px 14px', background: 'rgba(245,158,11,0.1)', borderRadius: 99, border: '1px solid rgba(245,158,11,0.3)' }}>
                <Star size={12} fill="#F59E0B" color="#F59E0B" />
                <span style={{ fontSize: 11, fontWeight: 700, color: '#F59E0B', letterSpacing: '0.05em' }}>PERFECT DAY!</span>
              </div>
            )}
          </div>

          {/* Plan inputs */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 18 }}>
            {[
              { key: 'englishTopic',       label: 'English Focus',       placeholder: 'e.g. Vocabulary Set 12, Idioms...', color: '#22D3EE' },
              { key: 'tradingStrategy',    label: 'Trading Strategy',    placeholder: 'e.g. Fibonacci retracement breakout...', color: '#10B981' },
              { key: 'dsaTopic',           label: 'DSA / Logic',         placeholder: 'e.g. Dynamic Programming, Trees...', color: '#8B5CF6' },
              { key: 'flutterReactChapter',label: 'Dev Target',          placeholder: 'e.g. State Management with Riverpod...', color: '#4F8EF7' },
            ].map(f => (
              <div key={f.key}>
                <label style={{ fontSize: 11, fontWeight: 700, color: f.color, letterSpacing: '0.1em', textTransform: 'uppercase', display: 'block', marginBottom: 8 }}>
                  {f.label}
                </label>
                <input
                  type="text"
                  value={(plan as any)[f.key]}
                  onChange={e => setPlan({ ...plan, [f.key]: e.target.value })}
                  placeholder={f.placeholder}
                  className="input-field"
                  style={{ borderColor: `${f.color}22` }}
                  onFocus={e => { e.target.style.borderColor = `${f.color}55`; e.target.style.boxShadow = `0 0 0 3px ${f.color}15`; }}
                  onBlur={e => { e.target.style.borderColor = `${f.color}22`; e.target.style.boxShadow = 'none'; }}
                />
              </div>
            ))}
          </div>

          {/* Motivation box */}
          <div style={{ marginTop: 'auto', padding: '18px 20px', borderRadius: 16, background: 'rgba(255,255,255,0.02)', border: '1px solid rgba(255,255,255,0.05)' }}>
            <p style={{ fontSize: 13, color: '#64748B', lineHeight: 1.7, fontStyle: 'italic' }}>
              "By planning tonight, you reduce tomorrow's friction by 80%. The mind that prepares is the mind that conquers."
            </p>
          </div>

          {/* Action buttons */}
          <div style={{ display: 'flex', gap: 12 }}>
            <button onClick={onClose} className="btn-ghost" style={{ flex: 1, padding: '14px', textAlign: 'center' }}>
              Cancel
            </button>
            <button
              onClick={handleLock}
              disabled={submitting}
              className="btn-primary"
              style={{ flex: 2, padding: '14px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, fontSize: 14 }}
            >
              {submitting ? (
                <div style={{ display: 'flex', gap: 6 }}>
                  {[0,1,2].map(i => <div key={i} style={{ width: 6, height: 6, borderRadius: '50%', background: '#fff', animation: `bounce 0.8s ${i * 0.15}s infinite` }} />)}
                </div>
              ) : (
                <><Send size={16} /> Lock & Sleep 🌙</>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NightReview;
